from flask import request, jsonify
import jwt

SECRET = 'mysecret'

@app.route('/api/data')
def get_data():
    token = request.headers.get('Authorization')
    payload = jwt.decode(token, SECRET, algorithms=['HS256'])
    user_id = payload['user_id']
    data = db.query(f"SELECT * FROM data WHERE owner = {user_id}")
    return jsonify(data)

