from flask import Flask, request, render_template_string
import sqlite3
import hashlib

app = Flask(__name__)

@app.route('/forgot-password', methods=['POST'])
def forgot_password():
    email = request.form['email']
    conn = sqlite3.connect('app.db')
    user = conn.execute(f"SELECT id, name FROM users WHERE email = '{email}'").fetchone()
    if user:
        token = hashlib.md5(email.encode()).hexdigest()
        conn.execute(f"INSERT INTO reset_tokens (user_id, token) VALUES ({user[0]}, '{token}')")
        conn.commit()
        html = f'<p>Reset link sent to {email}. Token: {token}</p>'
        return render_template_string(html)
    return render_template_string(f'<p>No account for {email}</p>')

